"""Cuaderno del estudiante, 3.º básico Lenguaje y Comunicación, OA 23 (escucha literaria de obras completas) y OA 24 (comprensión de textos orales).

Los textos que un adulto lee en voz alta son originales y están escritos dentro de cada ejercicio.
No se reproducen mitos ni leyendas tradicionales. El mito y la leyenda de los ejemplos son textos originales breves, rotulados como inventados para este cuaderno; el adulto debe elegir además una obra tradicional de la biblioteca para la lectura completa.
"""
from __future__ import annotations

from student_lessons import ex, register

OA23, OA24 = "LE03 OA 23", "LE03 OA 24"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


POEMA = "«La luna en el patio se sienta a mirar. Los grillos le cantan canciones sin parar»"
ZAPATO = "«En el armario vivía un zapato rojo que miraba el cielo por la ventana. Cada noche decía: Algún día volaré. Los otros zapatos se reían de él»"
MITO = "(Mito inventado para este cuaderno, no es un mito tradicional) «Al principio del mundo, las noches eran muy oscuras. Una anciana tejedora, hija de la montaña, juntó polvo de cristal y lo lanzó al cielo. El polvo se quedó brillando y así nacieron las estrellas»"
LEYENDA = "(Leyenda inventada para este cuaderno, no es una leyenda tradicional) «Dicen los vecinos del pueblo que, en el cerro, una campana suena sola las noches de niebla. Cuentan que es la campana de un pastor que se perdió y que la hace sonar para guiar a quienes se extravían. Nadie ha visto la campana»"
MORA1 = "Episodio 1: Mora, una tortuga pequeña, vivía en un estanque junto a un río. Un día vio pasar una hoja grande flotando y quiso saber adónde iba. Decidió seguirla por la orilla."
MORA2 = "Episodio 2: Mora caminó hasta un lugar donde el río se hacía angosto. Allí encontró a un pato llamado Beto, atrapado entre unas ramas. Mora lo ayudó a salir empujando una rama con su caparazón."
MORA3 = "Episodio 3: Beto, agradecido, la llevó en su espalda por el agua hasta el mar. Mora vio las olas y se quedó mirando sin decir nada. Al caer la tarde, Beto la llevó de regreso al estanque. Ahora Mora sabía adónde iban las hojas."
MORA = MORA1 + " " + MORA2 + " " + MORA3
FABULA = "«Una luciérnaga presumía de su luz ante una vela. La vela dijo: Mi luz es más fuerte que la tuya. Entonces llegó el viento y apagó la vela. La luciérnaga siguió brillando y alumbró el camino de un niño que se había perdido. Moraleja: la luz que ayuda vale más que la que presume»"

