L(OA23, 1,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio. Siéntate cómodo, en un lugar tranquilo.",
  "Aprenderé a prepararme para escuchar una obra completa y a disfrutarla: sentarme cómodo, guardar silencio y formar imágenes en mi mente.",
  ["Sé escuchar con atención una lectura corta.", "Sé que una obra literaria puede ser un cuento, un poema o una fábula."],
  ["Una obra literaria puede ser un cuento, un poema, una fábula, un mito o una leyenda. Un cuento folclórico es un cuento que la gente contó de boca en boca durante años, sin autor conocido. Un mito explica cómo empezó algo del mundo, con seres extraordinarios. Una leyenda cuenta un hecho asombroso ligado a un lugar. Cuando un adulto la lee en voz alta, tú escuchas la obra completa, de principio a fin. Antes de empezar, siéntate cómodo y en silencio, y mira al lector.",
   "Escuchar una obra es más que oír palabras. Mientras escuchas, forma imágenes en tu mente. Una imagen es lo que ves con la imaginación. Si el texto dice «la luna se sienta en el patio», imagina la luna y el patio. También puedes anotar una duda para preguntarla al final, sin interrumpir.",
   "Antes de escuchar, mira el título y piensa de qué podría tratar. Si la obra es larga, puede leerse en episodios, que son sus partes. Al final de cada parte, recuerda lo que pasó. Así disfrutas más la historia y la comprendes mejor. Los textos de ejemplo de este cuaderno son inventados; el adulto puede leer además un mito o una leyenda tradicional de la biblioteca."],
  [("obra completa", "texto leído de principio a fin"), ("imagen", "lo que veo con la imaginación al escuchar"), ("episodio", "cada parte de una obra larga"), ("duda", "algo que no entiendo y quiero preguntar"), ("lector", "la persona que lee en voz alta")],
  [("Formar una imagen", f"Escucha: {POEMA}. ¿Qué imagen puedes ver en tu mente?", ["La luna aparece en un patio.", "Está sentada y mira.", "Los grillos cantan cerca."], "Una luna sentada en un patio con grillos que cantan"),
   ("Guardar una duda", "Escuchas un cuento y no entiendes la palabra «orilla». ¿Qué haces?", ["No quiero interrumpir la lectura.", "Anoto la palabra.", "La pregunto al final."], "Anoto la duda y la pregunto al final")],
  [("Conversar con un compañero durante la lectura.", "No escuchas y molestas a los demás.", "Guarda silencio hasta el final."), ("Escuchar solo un pedazo de la obra.", "No comprendes toda la historia.", "Escucha de principio a fin.")],
  ([E("Antes de escuchar una obra, ¿qué haces: sentarte cómodo y en silencio o conversar con tu compañero?", "Sentarme cómodo y en silencio", "Así puedes escuchar bien."),
    E("Una obra completa se escucha, ¿de principio a fin o solo el final?", "De principio a fin", "Así comprendes toda la historia."),
    E("Si no entiendes una palabra mientras escuchas, ¿anotas la duda para el final o interrumpes sin parar?", "Anoto la duda para el final", "Así no interrumpes la lectura.")],
   [E(f"Escucha: {POEMA}. ¿Qué hace la luna en el patio?", "Se sienta a mirar", "Lo dice el primer verso."),
    E(f"Escucha: {POEMA}. ¿Quiénes cantan?", "Los grillos", "Los grillos le cantan a la luna."),
    E("Un relato cuenta cómo nacieron las estrellas gracias a un ser extraordinario. ¿Se parece más a un mito o a un poema?", "A un mito", "El mito explica cómo empezó algo del mundo.")],
   [E("Antes de escuchar el cuento «El zapato que quería volar», ¿qué haces primero: pensar de qué podría tratar el título o buscar otro libro?", "Pensar de qué podría tratar el título", "El título da pistas."),
    E("El adulto te avisa que leerá un cuento en tres episodios. ¿Cuántas partes escucharás: 3 o 1?", "3", "Cada episodio es una parte."),
    E("Mientras escuchas, cierras los ojos un momento para ver la historia en tu mente, no para dormir. ¿Qué formas con la imaginación?", "Imágenes", "Imaginar escenas es formar imágenes.")],
   [E("Un niño conversa con su compañero durante la lectura. ¿Qué problema causa?", "No escucha y molesta a los demás", "La conversación interrumpe."),
    E("¿Por qué conviene mirar el título antes de escuchar?", "Porque ayuda a imaginar de qué trata", "El título da pistas de la obra.")],
   [E(f"Escucha: {POEMA}. Escribe las dos palabras del poema que riman al final de cada verso.", "Mirar y parar", "Las dos terminan en -ar."),
    E("Ordena lo que haces: a) escuchar la obra en silencio, b) conversar sobre ella, c) sentarte cómodo. Escribe las letras en orden.", "c, a, b", "Primero te preparas, luego escuchas y al final conversas.")]),
  [E("Tu profesora leerá una fábula completa. Tienes una duda sobre una palabra. ¿Cuándo la preguntas: durante la lectura o al final?", "Al final", "Así no interrumpes.")],
  [E("En Lenguaje: ¿Qué es una imagen al escuchar?", "Lo que veo con la imaginación", "Se forma en la mente."),
   E("¿Cómo me siento antes de escuchar: cómodo o inquieto?", "Cómodo", "Así puedo atender."),
   E("¿Qué es un episodio?", "Cada parte de una obra larga", "Una obra puede leerse por partes.")],
  ("Pide a una persona que lea en voz alta este poema: «El viento peina los pinos y los pinos suspiran. Una nube pasa lenta y los pájaros la miran». Antes de escucharlo, escribe qué crees que tratará con el título «El viento peina los pinos». Después de escucharlo, dibuja o escribe una imagen que formaste. Anota una duda si la tuviste.", "Antes: tratará del viento en un bosque. Después: imagen de pinos que se mueven y una nube. Duda: ¿qué significa suspirar?", ["se prepara antes de escuchar", "escucha en silencio de principio a fin", "describe una imagen formada"], ["una predicción escrita", "un dibujo o texto de una imagen", "una duda anotada"], ["interrumpir la lectura", "no formar imágenes"], "Cuéntale a otra persona qué imagen viste mientras escuchabas."),
  "Escucha hoy un cuento o un poema completo y cuenta qué imagen formaste.",
  "Pide a un adulto que lea un poema y dibuja la imagen que más te gustó.")

L(OA23, 2,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a anticipar de qué tratará una obra con pistas, sin dar la respuesta por cerrada: puedo cambiar mi idea cuando la lectura sigue.",
  ["Sé prepararme para escuchar una obra.", "Sé formar imágenes con lo que escucho."],
  ["Anticipar es pensar qué puede pasar. Puedes anticipar con el título, una ilustración o lo que ya se leyó. Por ejemplo, con el título «El zapato que quería volar» puedes pensar que el zapato intentará volar y que alguien lo ayudará.",
   "Una buena anticipación tiene una razón: «Creo que intentará volar porque el título dice que quería volar». Pero anticipar no es adivinar sin fijarse. Es una idea que puedes cambiar si la historia dice otra cosa.",
   "Mientras la obra avanza, compara tu idea con lo que escuchas. Si coincide, sigue. Si no coincide, cambia tu idea y mira por qué. Así no cierras tu pensamiento y escuchas con más atención."],
  [("anticipar", "pensar qué puede pasar usando pistas"), ("pista", "dato que ayuda a pensar"), ("predicción", "idea sobre lo que va a pasar"), ("confirmar", "comprobar que algo es cierto"), ("cambiar de idea", "pensar algo distinto cuando hay nueva información")],
  [("Anticipar con el título", "El título es «El zapato que quería volar». ¿Qué puedes anticipar?", ["El título dice que el zapato quería volar.", "Puede intentar volar.", "Mi idea puede cambiar."], "Que el zapato intentará volar"),
   ("Cambiar de idea", f"Escuchas: {ZAPATO}. Pensabas que el zapato era feliz. ¿Qué pasa con tu idea?", ["Los otros zapatos se ríen de él.", "Eso muestra que quizás sufre burlas.", "Cambio mi idea."], "Cambio mi idea: tal vez está triste o solo")],
  [("Dar mi predicción como una verdad segura.", "La historia puede cambiar.", "Di «creo que» y comprueba."), ("Anticipar sin pistas.", "No tiene razón.", "Usa el título o lo que escuchaste.")],
  ([E("Anticipar es pensar qué puede pasar usando…", "Pistas", "Se basa en datos."),
    E("Si mi idea no coincide con la historia, ¿la cambio o la dejo igual?", "La cambio", "La historia es la guía."),
    E("«Creo que intentará volar porque el título dice que quería volar». ¿Esta anticipación tiene una razón? Responde sí o no.", "Sí", "La razón está en el título.")],
   [E("Con el título «El zapato que quería volar», ¿qué predicción tiene apoyo: que el zapato intentará volar o que se hará pan?", "Que el zapato intentará volar", "El título habla de volar."),
    E(f"Escucha: {ZAPATO}. ¿Qué pista muestra que otros no creen en el zapato?", "Los otros zapatos se reían de él", "La risa muestra burla."),
    E("Si escuchas «El zapato saltó por la ventana», ¿tu idea de que intentará volar se confirma o se cambia?", "Se confirma", "Saltar por la ventana es intentar volar.")],
   [E(f"Escucha: {ZAPATO}. ¿Qué crees que hará el zapato después, con apoyo en el texto: intentar volar o dormir para siempre?", "Intentar volar", "Cada noche dice que algún día volará."),
    E("Un niño dice «El zapato volará seguro, lo sé». ¿Qué le falta a su predicción: una razón en el texto o un dibujo?", "Una razón en el texto", "Una predicción necesita pistas."),
    E("Escuchas: «El zapato probó volar con unas alas de papel. Lo hizo solo, de noche, y nadie lo ayudó». Tu predicción era que lo ayudarían. ¿La mantienes o la cambias?", "La cambio", "El texto dice que nadie lo ayudó.")],
   [E("Dos niños anticipan. Uno dice «Quizás intente volar, pero puede cambiar». El otro dice «Seguro vuela». ¿Quién deja abierta su idea?", "El primero", "Reconoce que puede cambiar."),
    E("¿Por qué es útil volver a mirar mi predicción mientras avanza la historia?", "Porque puedo comprobar si estaba en lo cierto", "Se compara con lo que ocurre.")],
   [E(f"Escucha: {ZAPATO}. Escribe una pista del texto que apoye pensar que el zapato intentará algo.", "Cada noche decía: Algún día volaré", "Muestra su deseo."),
    E("Escuchas el inicio de un cuento: «Una niña encontró un mapa en la arena». Elige una predicción con apoyo: «buscará un tesoro» o «el mapa se convertirá en pan».", "Buscará un tesoro", "Un mapa suele guiar a un lugar.")]),
  [E("Vas a escuchar «El zapato que quería volar». Dibujas en el cuaderno un zapato con alas. ¿Qué anticipación coincide con tu dibujo: «Intentará volar» o «Vivirá bajo el mar»?", "Intentará volar", "El dibujo coincide con volar.")],
  [E("En Lenguaje: ¿Qué es anticipar?", "Pensar qué puede pasar usando pistas", "Es una idea sobre lo que viene."),
   E("¿Puedo cambiar mi anticipación? Responde sí o no.", "Sí", "La historia puede decir otra cosa."),
   E("¿Qué necesita una buena predicción?", "Una razón o pista", "Debe apoyarse en datos.")],
  ("Escucha este inicio que lee un adulto: «En la plaza había una banca vieja. Cada tarde, un niño se sentaba allí con un cuaderno y miraba las palomas». Escribe tu anticipación sobre qué hará el niño, con una razón del texto. Luego escucha este segundo trozo: «Dibujaba cada paloma y le ponía un nombre». Escribe si tu idea se confirma o la cambias.", "Anticipo que dibujará, porque tiene un cuaderno y mira palomas. Se confirma.", ["anticipa con una razón", "compara con el segundo trozo", "dice si confirma o cambia"], ["una anticipación con razón", "una conclusión"], ["predecir sin razón", "cerrarse a una sola idea"], "Cuéntale tu idea a otra persona y pregunta qué piensa."),
  "Antes de leer un libro, mira la portada y di qué crees que pasará.",
  "Elige el título de un cuento y escribe dos predicciones distintas, con una razón cada una.")

L(OA23, 3,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los episodios escritos en cada ejercicio.",
  "Aprenderé a recordar lo que pasó en cada episodio de una obra para entender la historia completa.",
  ["Sé anticipar lo que puede pasar.", "Sé escuchar un texto de principio a fin."],
  ["Algunas obras se leen por episodios, es decir, en partes. Entre un episodio y otro pasa tiempo, y es fácil olvidar. Para sostener la memoria, al comenzar el siguiente episodio recuerda qué pasó antes: quién es el personaje, qué quiere y qué ocurrió.",
   "Puedes anotar palabras clave de cada episodio. Por ejemplo, en el cuento de la tortuga Mora: episodio 1, hoja y río; episodio 2, pato atrapado; episodio 3, mar y regreso. Con esas palabras puedes volver a contar la historia en orden.",
   "También ayuda preguntarse tres cosas: ¿quién?, ¿qué pasó? y ¿por qué? Si entiendes los episodios anteriores, entenderás mejor el siguiente. Recordar es parte de escuchar bien una obra completa."],
  [("episodio", "cada parte de una obra larga"), ("sostener la memoria", "recordar lo que pasó antes"), ("palabra clave", "palabra que resume una parte"), ("orden", "primero, luego y al final"), ("personaje", "quien vive la historia")],
  [("Recordar el episodio 1", f"Escucha: {MORA1} ¿Qué quería saber Mora?", ["Mora vio pasar una hoja.", "Quiso saber adónde iba.", "Decidió seguirla."], "Adónde iba la hoja"),
   ("Ordenar los episodios", "Ordena: a) Mora llega al mar; b) Mora ayuda a Beto; c) Mora sigue una hoja.", ["Primero Mora sigue la hoja.", "Después encuentra a Beto.", "Al final llega al mar."], "c, b, a")],
  [("Olvidar lo que pasó antes y escuchar como si empezara de nuevo.", "No comprendes cómo se conectan las partes.", "Recuerda el episodio anterior."), ("Confundir el orden de los episodios.", "Cambia la historia.", "Usa palabras clave en orden.")],
  ([E(f"Escucha: {MORA1} ¿Dónde vivía Mora?", "En un estanque junto a un río", "Lo dice el episodio 1."),
    E(f"Escucha: {MORA2} ¿Quién estaba atrapado entre unas ramas?", "Un pato llamado Beto", "Lo dice el episodio 2."),
    E(f"Escucha: {MORA3} ¿A dónde la llevó Beto?", "Al mar", "Lo dice el episodio 3.")],
   [E(f"Escucha: {MORA1} ¿Qué vio pasar Mora?", "Una hoja grande flotando", "Eso la hizo seguirla."),
    E(f"Escucha: {MORA2} ¿Cómo ayudó Mora a Beto?", "Empujando una rama con su caparazón", "Así lo liberó."),
    E(f"Escucha: {MORA3} ¿Qué sabía Mora al final?", "Adónde iban las hojas", "Por el río llegaban al mar.")],
   [E("Ordena estos cuatro hechos del cuento de Mora: a) Mora ve las olas; b) Mora ayuda a Beto; c) Mora ve pasar una hoja grande; d) Beto la lleva de regreso al estanque. Escribe las letras en orden.", "c, b, a, d", "Hoja, ayuda al pato, olas y regreso."),
    E(f"Escucha: {MORA} ¿Qué episodio cuenta cómo conoce Mora a Beto: el 1, el 2 o el 3?", "El 2", "Allí encuentra al pato."),
    E(f"Escucha: {MORA} ¿En qué episodio vuelve Mora al estanque: el 1 o el 3?", "El 3", "Beto la lleva de regreso.")],
   [E("¿Por qué Beto llevó a Mora hasta el mar?", "Porque estaba agradecido", "Mora lo había ayudado."),
    E("Un niño dice que Mora conoció a Beto en el mar. Según el episodio 2, ¿es cierto? Responde sí o no y por qué.", "No, lo conoció cerca del río, entre unas ramas", "El encuentro fue donde el río se hacía angosto.")],
   [E("Para recordar el cuento de Mora, ¿qué palabras clave sirven, una por episodio: «hoja, pato, mar» o «lápiz, goma, mesa»?", "Hoja, pato, mar", "Resumen cada episodio."),
    E(f"Escucha: {MORA3} ¿Qué hizo Mora cuando vio las olas?", "Se quedó mirando sin decir nada", "Lo dice el episodio 3.")]),
  [E("Mañana se leerá el episodio 3 del cuento de Mora. Para recordar el episodio 2, ¿qué pregunta te haces: «¿Quién estaba atrapado?» o «¿Qué color tiene mi lápiz?»", "¿Quién estaba atrapado?", "Esa pregunta recuerda lo importante.")],
  [E("¿Para qué recuerdo lo que pasó antes?", "Para entender mejor el siguiente episodio", "Las partes se conectan."),
   E("¿Qué tres preguntas ayudan: quién, qué pasó y por qué?", "Quién, qué pasó y por qué", "Resumen cada episodio."),
   E("En Lenguaje: ¿Qué son las palabras clave?", "Palabras que resumen una parte", "Ayudan a recordar.")],
  ("Escucha esta historia en tres partes que lee un adulto. Episodio 1: «Nico perdió su gorro en el parque». Episodio 2: «Un perro lo encontró y lo llevó a una niña». Episodio 3: «La niña buscó a Nico y le devolvió el gorro». Escribe una palabra clave por episodio y, con esas tres palabras, cuenta la historia con tus palabras.", "Palabras clave: gorro, perro, devolvió. «Nico perdió su gorro, un perro lo llevó a una niña y ella se lo devolvió».", ["escribe una palabra clave por episodio", "cuenta la historia en orden", "no inventa partes que no están"], ["tres palabras clave", "resumen oral o escrito"], ["cambiar el orden", "olvidar un episodio"], "Cuéntale la historia a otra persona y pregunta si la entendió."),
  "Antes de escuchar la siguiente parte de un cuento, recuerda en voz alta qué pasó antes.",
  "Escribe tres palabras clave de una historia que conozcas y cuéntala en orden.")

L(OA23, 4,
  "Este cuaderno, lápiz y un adulto que lea en voz alta las fábulas y pasajes escritos en cada ejercicio.",
  "Aprenderé a conversar sobre un pasaje de una obra, diciendo lo que pienso y sintiendo con razones del texto.",
  ["Sé recordar lo que pasa en una historia.", "Sé escuchar a otras personas."],
  ["Una conversación literaria es un diálogo sobre una obra: qué te pareció, qué pensaste y qué sentiste. Para conversar bien, escoge un pasaje, es decir, un trocito de la obra, y di tu reacción: «Me gustó cuando…», «Me pareció curioso que…».",
   "Tu reacción debe tener una razón del texto: «Me pareció justo que la luciérnaga siguiera brillando, porque ayudó a un niño perdido». Una razón se basa en lo que pasó, no solo en «porque sí». También escucha a los demás y respeta sus ideas distintas.",
   "En las fábulas hay una moraleja, que es una enseñanza al final. Puedes conversar sobre ella: ¿estás de acuerdo?, ¿por qué? Una buena conversación tiene turnos para hablar, preguntas y respeto. También se conversa sobre mitos y leyendas: el mito explica cómo empezó algo del mundo y la leyenda cuenta un hecho asombroso de un lugar; los de este cuaderno son inventados."],
  [("conversación literaria", "diálogo sobre una obra"), ("pasaje", "trocito de una obra"), ("reacción", "lo que pienso o siento al escuchar"), ("moraleja", "enseñanza al final de una fábula"), ("razón", "dato del texto que apoya mi opinión")],
  [("Dar una reacción con razón", f"Escucha: {FABULA}. Una niña dice: «Me gustó la luciérnaga porque siguió brillando y ayudó». ¿Tiene una razón del texto?", ["Dice que siguió brillando.", "También dice que ayudó.", "Ambas cosas están en la fábula."], "Sí, usa lo que ocurre en la fábula"),
   ("Identificar la moraleja", f"Escucha: {FABULA}. ¿Cuál es la moraleja?", ["La moraleja está al final.", "Dice que la luz que ayuda vale más."], "La luz que ayuda vale más que la que presume")],
  [("Decir «me gustó» sin ninguna razón.", "La conversación no avanza.", "Agrega «porque» y un dato del texto."), ("Inventar algo que no pasó.", "Cambia la obra.", "Basa tu idea en lo que dice el texto.")],
  ([E(f"Escucha: {FABULA}. ¿Qué hizo la luciérnaga cuando el viento apagó la vela?", "Siguió brillando", "Lo dice la fábula."),
    E(f"Escucha: {LEYENDA} ¿Qué suena solo en el cerro las noches de niebla?", "Una campana", "Lo dice la leyenda."),
    E("En una fábula, la enseñanza final se llama…", "Moraleja", "Eso es la moraleja.")],
   [E(f"Escucha: {FABULA}. ¿A quién alumbró la luciérnaga?", "A un niño que se había perdido", "Lo dice el texto."),
    E(f"Escucha: {FABULA}. ¿Quién apagó la vela: el viento o la luciérnaga?", "El viento", "El viento apagó la vela."),
    E("Dices «Me gustó cuando la luciérnaga ayudó al niño». ¿Es una reacción con apoyo en el texto? Responde sí o no.", "Sí", "Habla de algo que pasa.")],
   [E(f"Escucha: {FABULA}. Una reacción con razón: «Me pareció justo que siguiera brillando, ___ ayudó a un niño». Completa con porque o pero.", "Porque", "La razón sigue a porque."),
    E(f"Escucha: {FABULA}. ¿Cuál reacción se apoya en el texto: «La vela era más fuerte hasta que llegó el viento» o «La vela vivía en el mar»?", "La vela era más fuerte hasta que llegó el viento", "Eso ocurre en la fábula."),
    E(f"Escucha: {MITO} ¿Qué explica este mito: cómo nacieron las estrellas o cómo se hace el pan?", "Cómo nacieron las estrellas", "El mito cuenta cómo empezó algo del mundo.")],
   [E("Un niño dice «No me gustó» y no da razón. ¿Qué le puedes preguntar para que explique?", "¿Por qué?", "Pide una razón."),
    E("¿Por qué una opinión debe apoyarse en lo que dice el texto?", "Para que sea creíble y no inventada", "Se basa en la obra.")],
   [E(f"Escucha: {FABULA}. ¿Qué parte te gustó más? Elige una con razón: «Cuando la luciérnaga alumbró al niño, porque ayudó» o «Cuando la vela, porque sí».", "Cuando la luciérnaga alumbró al niño, porque ayudó", "Tiene una razón basada en el texto."),
    E(f"Escucha: {FABULA}. Una niña está de acuerdo con la moraleja. ¿Qué razón del texto la apoya: «la luciérnaga ayudó al niño mientras la vela se apagó» o «la vela vivía en el mar»?", "La luciérnaga ayudó al niño mientras la vela se apagó", "La razón usa lo que ocurre.")]),
  [E("En tu curso conversan sobre un cuento. Dices: «Me gustó el final porque el protagonista cumplió su deseo». ¿Usaste una razón del texto? Responde sí o no.", "Sí", "Apoyas tu gusto en un hecho del cuento.")],
  [E("¿Qué es un pasaje?", "Un trocito de la obra", "Es una parte pequeña."),
   E("¿Qué palabra introduce una razón: porque o pero?", "Porque", "Introduce la causa."),
   E("En una conversación literaria, ¿se respetan las ideas distintas? Responde sí o no.", "Sí", "Cada persona puede pensar distinto.")],
  ("Pide a un adulto que lea esta fábula: «Un gallo cantaba muy fuerte cada mañana y los vecinos se quejaban. Un día se quedó sin voz. Aquella mañana nadie despertó y llegaron tarde a todo. Moraleja: lo que molesta a veces es lo que más ayuda». Escribe una reacción de dos oraciones: una que diga qué te gustó o pensaste, y otra con una razón del texto. Conversa con otra persona sobre la moraleja.", "Me pareció curioso que, sin el canto del gallo, nadie despertara. Lo digo porque llegaron tarde a todo.", ["da una reacción", "usa una razón del texto", "respeta las ideas de otros"], ["dos oraciones escritas", "conversación breve"], ["opinar sin razón", "inventar hechos"], "Pregunta a la otra persona si está de acuerdo y por qué."),
  "Cuenta a alguien un pasaje de un cuento que te gustó y di por qué.",
  "Escribe dos frases con «Me gustó... porque...» sobre un cuento que conozcas.")

L(OA23, 5,
  "Este cuaderno, lápiz, papel y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a responder de manera creativa a una obra (dibujo, carta, nuevo final o voz de un personaje), respetando lo que dice el texto.",
  ["Sé conversar sobre un pasaje.", "Sé recordar lo que pasa en una historia."],
  ["Responder creativamente a una obra es expresar lo que sentiste con tus propias ideas: puedes dibujar una escena, escribir una carta a un personaje, inventar otro final o imaginar qué diría un personaje. Tu respuesta debe mostrar que entendiste la obra.",
   "Una respuesta creativa respeta los hechos del texto, pero agrega algo tuyo. Si dibujas la escena de Mora y el mar, debes incluir a Mora, las olas y a Beto, porque están en el cuento. Puedes agregar colores, un cielo o un sol que tú imaginaste.",
   "También puedes cambiar un final, pero explicando cómo y por qué. Para decidir, revisa tres cosas: ¿mantengo a los personajes?, ¿respeto lo que ya pasó? y ¿mi idea agrega algo nuevo? Si las tres son sí, tu respuesta es creativa y fiel."],
  [("respuesta creativa", "expresar con ideas propias lo que sentí de una obra"), ("fiel", "que respeta lo que dice el texto"), ("final alternativo", "otro final inventado"), ("escena", "momento de una historia"), ("personaje", "quien vive la historia")],
  [("Dibujar una escena fiel", "Escuchas: «Mora vio las olas y se quedó mirando». ¿Qué debe tener tu dibujo?", ["Está Mora.", "Están las olas.", "Puedo agregar colores."], "Mora y las olas, más lo que yo agregue"),
   ("Escribir una carta", "Quieres escribirle una carta a Beto. ¿Qué dices para ser fiel a la historia?", ["Puedo agradecer lo que hizo.", "Hablo del viaje al mar.", "No invento cosas que contradicen el cuento."], "Le agradezco por llevar a Mora al mar")],
  [("Dibujar algo que no está en la obra como si fuera parte.", "No respeta el texto.", "Incluye personajes y hechos del cuento."), ("Cambiar el final sin explicar.", "No se entiende por qué.", "Cuenta qué cambia y por qué.")],
  ([E("Una respuesta creativa a una obra puede ser un dibujo, una carta o un final nuevo. ¿Debe mostrar que entendí la obra? Responde sí o no.", "Sí", "Debe basarse en lo que pasó."),
    E("Si dibujo la escena de Mora en el mar, ¿debo incluir a Mora y a las olas? Responde sí o no.", "Sí", "Están en el cuento."),
    E(f"Escucha: {MITO} ¿Qué dibujo es fiel a este mito: una anciana que lanza polvo de cristal brillante al cielo oscuro o una anciana que pesca en un lago?", "Una anciana que lanza polvo de cristal brillante al cielo oscuro", "Eso hace la anciana en el mito.")],
   [E(f"Escucha: {MORA3} ¿Quién llevó a Mora en su espalda por el agua?", "Beto", "Lo dice el episodio 3."),
    E("Quieres escribir una carta a Mora. ¿Qué es fiel al cuento: felicitarla por llegar al mar o decirle que viviste con ella en el mar?", "Felicitarla por llegar al mar", "Eso ocurre en el cuento."),
    E("Un final alternativo dice: «Mora se quedó a vivir en el mar». ¿Es igual al final del cuento? Responde sí o no.", "No", "En el cuento Mora vuelve al estanque; esto es un final nuevo.")],
   [E("¿Cuál dibujo es fiel al cuento: una tortuga con un pato en el río o un elefante con un cohete?", "Una tortuga con un pato en el río", "Son personajes del cuento."),
    E(f"Escucha: {FABULA}. ¿Qué incluyes en un dibujo fiel: una luciérnaga que alumbra a un niño o un barco en el mar?", "Una luciérnaga que alumbra a un niño", "Es una escena de la fábula."),
    E("¿Cuál frase sirve para una carta a la luciérnaga: «Gracias por ayudar al niño» o «Gracias por vivir en el mar»?", "Gracias por ayudar al niño", "Eso hizo en la fábula.")],
   [E("Una niña escribió un final donde la vela se enciende sola, pero no explicó cómo. ¿Qué le falta: decir cómo y por qué o agregar un dibujo?", "Decir cómo y por qué", "Un final nuevo debe explicarse."),
    E("¿Por qué una respuesta creativa debe respetar los hechos del texto?", "Para mostrar que entendí la obra", "Si los cambia sin sentido, no se ve comprensión.")],
   [E("Con el cuento de Mora, elige el final nuevo que respeta la historia: «Mora y Beto se hicieron amigos y volvieron a visitar el mar» o «Mora no existió».", "Mora y Beto se hicieron amigos y volvieron a visitar el mar", "Mantiene a los personajes y agrega algo nuevo."),
    E(f"Escucha: {FABULA}. Escribe qué le dirías a la vela en una carta, con una razón del texto.", "Vela, el viento te apagó, pero la luciérnaga siguió ayudando", "Usa un hecho de la fábula.")]),
  [E("Para el cierre de la lectura, tu curso dibujará la parte favorita del cuento de Mora. Tú dibujas a Mora mirando las olas. ¿Es fiel al cuento? Responde sí o no.", "Sí", "Mora mira las olas en el episodio 3.")],
  [E("¿Qué debe tener una respuesta creativa a una obra?", "Algo mío y los hechos del texto", "Es creativa y fiel."),
   E("¿Se puede cambiar un final? Responde sí o no.", "Sí", "Si explico cómo y por qué."),
   E("¿Qué debo mantener al hacer un dibujo de una escena?", "A los personajes y hechos", "Así es fiel al texto.")],
  ("Elige una de estas respuestas creativas para el cuento de Mora y Beto: A) dibujar la escena del mar, B) escribir una carta de Mora a Beto, C) inventar otro final. Hazla en una hoja. Escribe tres frases que expliquen cómo respetaste el cuento y qué agregaste tú.", "Escogí B. Escribí: «Querido Beto, gracias por llevarme al mar». Respeté que Beto la llevó, y agregué que ella le regala una hoja bonita.", ["respeta los hechos", "agrega algo propio", "explica lo que hizo"], ["una hoja con la respuesta", "tres frases de explicación"], ["contradecir hechos del cuento", "no explicar el cambio"], "Muestra tu trabajo a otra persona y pregunta si reconoce el cuento."),
  "Dibuja una escena de un cuento y agrégale un detalle tuyo.",
  "Inventa otro final para el cuento de Mora y explica por qué lo imaginaste.")

# ------------------------------------------------------------------ OA 24
LAVAR = "«Para lavarte las manos, primero moja tus manos con agua. Después ponte jabón y frota las palmas, el dorso y entre los dedos durante unos veinte segundos. Por último, enjuaga y sécate con una toalla limpia»"
HUERTO = "«Hoy, los estudiantes de tercero de la escuela Los Alerces plantaron un huerto en el patio. Sembraron lechugas y zanahorias. Cada semana, un grupo distinto regará las plantas»"
ANECDOTA = "«Ayer, camino al colegio, se me cayó el lápiz en un charco. Lo saqué rápido, pero quedó lleno de barro. Me reí mucho porque parecía un lápiz de chocolate»"
ABEJAS = "«Las abejas visitan las flores para tomar néctar. Mientras lo hacen, el polen se pega a su cuerpo y pasa a otras flores. Así ayudan a que las plantas den frutos»"
TALLER = "«El taller de reciclaje será el martes 12 a las 15 horas en la sala 4. Cada niño debe llevar dos botellas plásticas limpias y una cinta adhesiva. El taller dura una hora y lo dirige la profesora Ana»"
PASEO = "«Mañana iremos de paseo a un museo. Saldremos temprano y llevaremos almuerzo. Se necesita una autorización firmada»"
LLUVIA = "«La lluvia se forma cuando el sol calienta el agua del mar, de los ríos y de los lagos. El agua sube convertida en vapor y se junta en las nubes. Cuando las nubes pesan mucho, el agua cae como lluvia»"
NOTICIA = "«Ayer llovió con fuerza en un pueblo del sur de Chile. Las calles se mojaron y los vecinos usaron paraguas. Hoy habrá sol por la tarde»"
LUIS = "«Cuando llegué al patio, Luis estaba sentado solo. Tenía su mochila a un lado y miraba el suelo. Nadie le hablaba»"
LLEGO = "«Llegó mi tía muy tarde. Traía bolsas llenas, se frotaba las manos rojas y temblaba un poco. Se sentó cerca de la estufa»"
DOCUMENTAL = "(Voz de un documental, texto original para este cuaderno) «En el fondo del mar vive el pulpo. Tiene ocho brazos y puede cambiar de color para esconderse. Si siente peligro, lanza una nube de tinta»"
PELICULA = "(Escena de una película, texto original para este cuaderno) «La niña abre la puerta, ve la sala llena de globos y se tapa la boca con las manos, sonriendo»"

L(OA24, 1,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a identificar el propósito de un texto oral (explicar, dar instrucciones, informar o contar) y la situación en que se dice.",
  ["Sé escuchar con atención.", "Sé el propósito de un texto escrito."],
  ["Los textos orales son los que se dicen en voz alta: una explicación, una instrucción, una noticia o una anécdota. Para comprenderlos, primero pregúntate quién habla, a quién le habla y para qué lo dice. El para qué es el propósito.",
   "Hay varios propósitos. Dar instrucciones es decir cómo hacer algo paso a paso. Explicar es mostrar por qué o cómo ocurre algo. Informar, como en una noticia, es contar un hecho reciente. Contar una anécdota es relatar algo que me pasó, a veces para entretener. Un documental tiene imágenes y una voz que informa sobre un tema real, como los animales. Una película cuenta una historia con personajes. También se pueden escuchar y comprender.",
   "También importa la situación: dónde y cuándo se dice. Una noticia se oye en la radio o en el noticiero; una instrucción se dice cuando alguien va a hacer una tarea. Si sabes la situación y el propósito, entiendes mejor lo que escuchas."],
  [("texto oral", "texto que se dice en voz alta"), ("propósito", "la razón por la que se dice algo"), ("instrucción", "texto que dice cómo hacer algo"), ("noticia", "texto que informa un hecho reciente"), ("anécdota", "relato breve de algo que pasó")],
  [("Identificar el propósito", f"Escucha: {LAVAR} ¿Cuál es su propósito?", ["Dice qué hacer en orden.", "Usa primero, después y por último.", "Dar instrucciones."], "Dar instrucciones"),
   ("Identificar el propósito de una anécdota", f"Escucha: {ANECDOTA} ¿Qué propósito tiene?", ["Cuenta algo que le pasó.", "Se ríe de lo que ocurrió.", "Es una anécdota."], "Contar una anécdota")],
  [("Confundir una noticia con una anécdota.", "La noticia informa un hecho; la anécdota cuenta algo personal.", "Pregunta quién habla y para qué."), ("Solo escuchar los detalles sin pensar en el propósito.", "Pierdes la idea principal.", "Pregúntate ¿para qué lo dice?")],
  ([E("Los textos orales son los que se…", "Dicen en voz alta", "No se leen, se escuchan."),
    E("El propósito es la razón por la que se…", "Dice algo", "Responde para qué se habla."),
    E(f"Escucha: {LAVAR} ¿Es una instrucción o una noticia?", "Una instrucción", "Dice cómo hacer algo.")],
   [E(f"Escucha: {HUERTO} ¿Es una noticia o una anécdota?", "Una noticia", "Informa un hecho reciente."),
    E(f"Escucha: {ANECDOTA} ¿Quién habla: alguien que cuenta algo que le pasó o un reportero?", "Alguien que cuenta algo que le pasó", "Habla en primera persona."),
    E(f"Escucha: {ABEJAS} ¿Su propósito es explicar o dar instrucciones?", "Explicar", "Dice cómo ayudan las abejas.")],
   [E(f"Escucha: {LAVAR} ¿Para qué sirve: para lavarse las manos bien o para contar un paseo?", "Para lavarse las manos bien", "Dice cómo hacerlo."),
    E(f"Escucha: {HUERTO} ¿Qué hecho informa?", "Que plantaron un huerto", "Es el hecho principal."),
    E(f"Escucha: {ANECDOTA} ¿Por qué se rió el hablante?", "Porque el lápiz parecía de chocolate", "Lo dice al final.")],
   [E("Un adulto dice «Primero pega la hoja, después pinta». ¿Qué propósito tiene: dar instrucciones o contar una anécdota?", "Dar instrucciones", "Dice los pasos en orden."),
    E("Escuchas por la radio: «Hoy abrió un parque nuevo en la ciudad». ¿Es una noticia o una instrucción?", "Una noticia", "Informa un hecho reciente.")],
   [E(f"Escucha: {DOCUMENTAL} ¿Qué propósito tiene: dar información sobre un animal o contar una anécdota personal?", "Dar información sobre un animal", "Habla de cómo es el pulpo."),
    E("Escucha este texto: «Para hacer un barco de papel, doblas la hoja por la mitad. Luego doblas las puntas y levantas los lados». Escribe su propósito.", "Dar instrucciones", "Dice cómo hacer algo.")]),
  [E("En la radio de tu colegio dicen: «Mañana habrá reunión de curso a las 4». ¿Cuál es el propósito: informar o contar una anécdota?", "Informar", "Avisa un hecho próximo.")],
  [E("¿Cuál es el propósito de una instrucción?", "Decir cómo hacer algo", "Da los pasos en orden."),
   E("¿Qué preguntas me ayudan a entender la situación: quién habla, a quién y para qué?", "Quién habla, a quién y para qué", "Aclaran la situación."),
   E("¿Una noticia informa un hecho reciente? Responde sí o no.", "Sí", "Ese es su propósito.")],
  ("Pide a un adulto que lea tres mini textos: A) «Mezcla la harina con el agua y amasa durante cinco minutos». B) «Ayer me encontré con un perro que sabía dar la pata». C) «La escuela abrió su biblioteca nueva». Escribe el propósito de cada uno (instrucción, anécdota o noticia) y quién crees que lo dice.", "A: instrucción, quien enseña una receta. B: anécdota, una persona que cuenta algo que le pasó. C: noticia, un reportero o persona de la escuela.", ["identifica los tres propósitos", "dice quién habla", "los justifica brevemente"], ["tres propósitos escritos", "tres posibles hablantes"], ["confundir noticia y anécdota", "no pensar quién habla"], "Escucha de nuevo uno de los textos y comprueba tu respuesta."),
  "Escucha hoy un aviso o un programa y di cuál es su propósito.",
  "Escribe un texto de dos oraciones con un propósito claro y pide a alguien que lo adivine.")

L(OA24, 2,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a registrar la información explícita de un texto oral con notas breves y palabras clave.",
  ["Sé identificar el propósito de un texto oral.", "Sé escribir palabras clave."],
  ["La información explícita es la que el texto dice de manera directa. Si escuchas «El taller será el martes 12 a las 15 horas», el día, la fecha y la hora son información explícita. No tienes que adivinarla.",
   "Para recordarla, toma notas con palabras clave y números. No escribas oraciones largas: anota «martes 12», «15 h», «sala 4». Una buena nota responde a las preguntas ¿qué?, ¿cuándo?, ¿dónde? y ¿quién? Así luego puedes contar lo escuchado sin olvidar datos.",
   "Las horas pueden decirse de 0 a 24: 15 horas es lo mismo que las 3 de la tarde. Cuando escuches, atiende a los datos importantes: fechas, horas, lugares, cantidades y nombres. Si algo se te pasó, pide que repitan. Y comprueba tus notas con lo que dijo el hablante."],
  [("información explícita", "dato que el texto dice directamente"), ("nota", "anotación breve"), ("palabra clave", "palabra que resume un dato"), ("dato", "información precisa"), ("repetir", "decir otra vez")],
  [("Registrar datos", f"Escucha: {TALLER} ¿Qué anotas para saber cuándo y dónde es?", ["Escucho martes 12 y 15 horas.", "El lugar es la sala 4.", "Anoto palabras clave."], "Martes 12, 15 h, sala 4"),
   ("Registrar qué llevar", f"Escucha: {TALLER} ¿Qué debe llevar cada niño?", ["Cada niño debe llevar algo.", "Dos botellas plásticas limpias y cinta."], "Dos botellas plásticas limpias y una cinta adhesiva")],
  [("Escribir toda la oración y perder datos.", "Se tarda mucho en escribir.", "Anota solo palabras clave."), ("Inventar un dato que no se dijo.", "La información explícita es la que se dice.", "Anota solo lo que escuchaste.")],
  ([E(f"Escucha: {TALLER} ¿Qué día es el taller?", "El martes 12", "Lo dice el texto."),
    E(f"Escucha: {TALLER} ¿A qué hora es?", "A las 15 horas", "Lo dice el texto."),
    E(f"Escucha: {TALLER} ¿En qué sala es?", "En la sala 4", "Lo dice el texto.")],
   [E(f"Escucha: {TALLER} ¿Cuánto dura el taller?", "Una hora", "Lo dice el texto."),
    E(f"Escucha: {TALLER} ¿Quién dirige el taller?", "La profesora Ana", "Lo dice el texto."),
    E(f"Escucha: {TALLER} ¿Cuántas botellas hay que llevar?", "Dos", "Lo dice el texto.")],
   [E(f"Escucha: {TALLER} ¿Cuál es una buena nota: «martes 12, 15 h, sala 4» o «El taller de reciclaje será el martes 12 a las 15 horas en la sala 4»?", "Martes 12, 15 h, sala 4", "Una nota usa palabras clave."),
    E(f"Escucha: {TALLER} ¿Qué dos cosas debe llevar cada niño: botellas y cinta o tijeras y papel?", "Botellas y cinta", "Eso dice el texto."),
    E(f"Escucha: {TALLER} ¿Qué preguntas responde «martes 12, 15 h»: ¿cuándo? o ¿dónde?", "¿Cuándo?", "Dan fecha y hora.")],
   [E("Un niño anotó «el taller es el miércoles». ¿Es información explícita del texto? Responde sí o no y por qué.", "No, porque el texto dice martes", "No coincide con el texto."),
    E("¿Por qué conviene anotar números y nombres?", "Porque son datos fáciles de olvidar", "Ayudan a recordar con precisión.")],
   [E(f"Escucha: {TALLER} Escribe una nota con tres datos: día, hora y sala.", "Martes 12, 15 h, sala 4", "Reúne los datos principales."),
    E(f"Escucha: {TALLER} Si el taller empieza a las 15 horas y dura una hora, ¿a qué hora termina?", "A las 16 horas", "15 más 1 es 16.")]),
  [E("En el patio se anuncia por parlante: «Mañana la biblioteca cierra a las 4 y abre a las 9». ¿Cuál es la hora de cierre?", "A las 4", "Es el dato explícito del anuncio.")],
  [E("¿Qué es la información explícita?", "La que el texto dice directamente", "No se adivina."),
   E("Para tomar notas, ¿escribo palabras clave u oraciones largas?", "Palabras clave", "Son breves y útiles."),
   E("Si no escuché un dato, ¿qué hago?", "Pido que lo repitan", "Así lo registro bien.")],
  ("Pide a un adulto que lea esto: «El sábado 5 habrá una feria del libro en la plaza, de 10 a 14 horas. Habrá cuentos para niños a las 11 y a las 12. La entrada es gratuita». Escribe una nota con cuatro datos: día, lugar, horario y cuántos cuentos. Luego cuéntale la información a otra persona usando tus notas.", "Sábado 5, plaza, 10 a 14 h, dos cuentos (11 y 12).", ["anota cuatro datos exactos", "usa palabras clave", "cuenta sin inventar"], ["nota con cuatro datos", "relato breve"], ["inventar datos", "escribir oraciones largas"], "Pregunta a la otra persona si le quedó claro."),
  "Escucha un aviso hoy y anota dos datos.",
  "Escribe un aviso de tres datos y pide a alguien que anote solo palabras clave.")

L(OA24, 3,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a conectar lo que escucho con mis experiencias de forma pertinente, es decir, que ayuden a entender el texto.",
  ["Sé registrar información explícita.", "Sé lo que son experiencias propias."],
  ["Establecer conexiones es relacionar lo que escuchas con algo que ya viviste, viste o aprendiste. Si escuchas sobre abejas y recuerdas que viste abejas en un jardín, tu experiencia te ayuda a entender el texto.",
   "La conexión es pertinente cuando ayuda a comprender. «Vi abejas posadas en flores» es pertinente si el texto habla de que las abejas visitan flores. «Me gusta el helado» no ayuda a entender ese texto, aunque sea cierto.",
   "Para hacerlo, pregúntate: ¿esto me recuerda algo que viví? ¿ese recuerdo explica algo del texto? Usa solo experiencias que quieras compartir, sin datos privados. Una buena conexión se dice así: «Esto me recuerda a… porque…»."],
  [("conexión", "relación entre lo que escucho y algo que viví"), ("experiencia", "algo que viví, vi o aprendí"), ("pertinente", "que ayuda a entender"), ("relacionar", "unir dos ideas"), ("compartir", "contar a otros")],
  [("Elegir una conexión pertinente", f"Escucha: {ABEJAS} ¿Qué experiencia ayuda a entender: «Vi abejas en las flores de un jardín» o «Me gusta el helado»?", ["El texto habla de abejas y flores.", "La primera experiencia lo explica.", "La segunda no tiene relación."], "Vi abejas en las flores de un jardín"),
   ("Decir la conexión", "¿Cómo dices la conexión con la frase «Esto me recuerda a... porque...»?", ["Digo lo que me recuerda.", "Explico por qué se parece."], "Esto me recuerda a las abejas del jardín porque también visitaban flores")],
  [("Contar una experiencia que no tiene relación.", "No ayuda a entender el texto.", "Elige una que explique algo del texto."), ("Contar datos privados.", "No hace falta compartir lo privado.", "Elige experiencias que quieras compartir.")],
  ([E("Una conexión relaciona lo que escucho con algo que…", "Ya viví o aprendí", "Une el texto con mi experiencia."),
    E("Una conexión es pertinente cuando ayuda a…", "Entender el texto", "Eso significa pertinente."),
    E("¿Debo contar datos privados para conectar? Responde sí o no.", "No", "Solo comparto lo que quiero.")],
   [E(f"Escucha: {ABEJAS} ¿Qué experiencia se relaciona: «Vi abejas en las flores» o «Fui a un cumpleaños»?", "Vi abejas en las flores", "El texto habla de abejas y flores."),
    E(f"Escucha: {LAVAR} ¿Qué experiencia se relaciona: «Me lavo las manos antes de comer» o «Jugué al fútbol»?", "Me lavo las manos antes de comer", "El texto trata de lavarse las manos."),
    E(f"Escucha: {HUERTO} ¿Qué experiencia se relaciona: «Planté una semilla en un vaso» o «Vi una película»?", "Planté una semilla en un vaso", "El texto habla de plantar.")],
   [E(f"Escucha: {ABEJAS} Completa: «Esto me recuerda a las flores del parque, ___ las abejas las visitan». Elige porque o pero.", "Porque", "Introduce la relación."),
    E(f"Escucha: {HUERTO} ¿Cuál conexión es pertinente: «Mi curso también riega plantas» o «Mi mochila es verde»?", "Mi curso también riega plantas", "Se relaciona con regar un huerto."),
    E(f"Escucha: {ANECDOTA} ¿Cuál es una conexión pertinente: «A mí también se me cayó algo en un charco» o «Hoy hace calor»?", "A mí también se me cayó algo en un charco", "Se relaciona con la anécdota.")],
   [E("Un niño dice que el texto sobre abejas le recuerda a su equipo de fútbol. ¿Qué pregunta le ayuda a explicar la conexión: «¿Cómo se relacionan?» o «¿Cuántos goles hiciste?»", "¿Cómo se relacionan?", "Pide explicar la relación con el texto."),
    E("¿Por qué una conexión sin relación no ayuda a comprender?", "Porque no explica nada del texto", "No aporta al sentido.")],
   [E(f"Escucha: {ABEJAS} Escribe una conexión pertinente con «Esto me recuerda a...» usando flores.", "Esto me recuerda a un jardín con flores donde vi abejas", "Se relaciona con abejas y flores."),
    E(f"Escucha: {LAVAR} Elige la mejor conexión: «Mi curso se lava las manos antes de almorzar» o «Mi curso tiene un perro».", "Mi curso se lava las manos antes de almorzar", "Se relaciona con el texto.")]),
  [E("En la sala escuchan una explicación sobre cómo cuidar plantas. Tú recuerdas que regaste una planta ayer. ¿Es una conexión pertinente? Responde sí o no.", "Sí", "Se relaciona con cuidar plantas.")],
  [E("¿Qué hace una conexión pertinente?", "Ayuda a entender el texto", "Se relaciona con el contenido."),
   E("¿Qué frase uso para conectar?", "Esto me recuerda a... porque...", "Une el texto con mi experiencia."),
   E("¿Debo compartir todo lo que me pasó? Responde sí o no.", "No", "Comparto solo lo que quiero.")],
  ("Pide a un adulto que lea esto: «Los pájaros construyen nidos con ramitas y pasto. El nido protege los huevos del viento y de la lluvia». Escribe una conexión pertinente con tu experiencia usando «Esto me recuerda a... porque...». Luego escribe una experiencia que no sería pertinente y explica por qué.", "Esto me recuerda a un nido que vi en un árbol, porque tenía ramitas. No pertinente: «me gusta el chocolate», porque no explica nada del nido.", ["conecta con una experiencia pertinente", "usa la frase", "explica por qué otra no sería pertinente"], ["una conexión escrita", "una explicación"], ["conexión sin relación", "datos privados"], "Cuéntale tu conexión a otra persona y pregunta si la entendió."),
  "Escucha una explicación y di qué experiencia tuya se relaciona.",
  "Escribe dos conexiones pertinentes sobre un texto que escuchaste.")

L(OA24, 4,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a formular preguntas para aclarar dudas y profundizar la comprensión de un texto oral.",
  ["Sé registrar información explícita.", "Sé formular preguntas con ¿qué?, ¿cuándo?, ¿dónde? y ¿por qué?"],
  ["Cuando escuchas, puedes hacer preguntas. Una pregunta de aclaración sirve para entender lo que no quedó claro: «¿A qué museo vamos?». Una pregunta para profundizar sirve para saber más: «¿Por qué se necesita una autorización?».",
   "Antes de preguntar, piensa qué falta. Si el texto no dice la hora, pregunta «¿A qué hora salimos?». Si dice un dato pero quieres entender mejor, pregunta con ¿por qué? o ¿cómo? Espera tu turno y usa un tono respetuoso.",
   "Una buena pregunta es clara, corta y se relaciona con el texto. No preguntes algo que ya se dijo. Si ya sabes la respuesta, formula otra pregunta que te lleve más lejos."],
  [("pregunta de aclaración", "pregunta para entender lo que no quedó claro"), ("pregunta para profundizar", "pregunta para saber más"), ("turno", "momento en que me toca hablar"), ("respetuoso", "que trata bien a los demás"), ("dato faltante", "información que no se dijo")],
  [("Preguntar lo que falta", f"Escucha: {PASEO} ¿Qué pregunta aclara lo que falta?", ["El texto no dice a qué museo ni a qué hora.", "Pregunto el dato que falta.", "¿A qué hora salimos?"], "¿A qué hora salimos?"),
   ("Preguntar para profundizar", f"Escucha: {PASEO} ¿Qué pregunta ayuda a entender mejor?", ["Ya sé que hace falta autorización.", "Pregunto por qué.", "¿Para qué se necesita la autorización?"], "¿Para qué se necesita la autorización?")],
  [("Preguntar algo que ya se dijo.", "No avanza la comprensión.", "Escucha bien antes de preguntar."), ("Hacer preguntas muy largas.", "Cuesta entenderlas.", "Formula una pregunta corta.")],
  ([E(f"Escucha: {PASEO} ¿Qué dato no se dijo: la hora exacta de salida o que llevarán almuerzo?", "La hora exacta de salida", "El texto solo dice que saldrán temprano."),
    E("Una pregunta de aclaración sirve para…", "Entender lo que no quedó claro", "Sirve para aclarar dudas."),
    E("Una pregunta para profundizar sirve para…", "Saber más", "Lleva más lejos.")],
   [E(f"Escucha: {PASEO} ¿Es de aclaración o de profundizar la pregunta «¿A qué museo iremos?»", "De aclaración", "Pide un dato que falta."),
    E(f"Escucha: {PASEO} ¿Es de aclaración o de profundizar la pregunta «¿Por qué es importante la autorización?»", "De profundizar", "Pide una razón."),
    E(f"Escucha: {PASEO} ¿Qué pregunta repite lo que ya se dijo: «¿Qué llevaremos de almuerzo?» o «¿Llevaremos almuerzo?»", "¿Llevaremos almuerzo?", "Ya se dijo que sí.")],
   [E(f"Escucha: {ABEJAS} ¿Qué pregunta profundiza: «¿Por qué el polen pasa a otras flores?» o «¿Qué son las abejas?»", "¿Por qué el polen pasa a otras flores?", "Pide una razón más profunda."),
    E(f"Escucha: {TALLER} ¿Qué pregunta aclara: «¿Qué hacemos con las botellas?» o «¿Cuánto mide la sala?»", "¿Qué hacemos con las botellas?", "Aclara una parte del taller."),
    E(f"Escucha: {HUERTO} ¿Qué pregunta profundiza: «¿Cómo cuidan las lechugas?» o «¿Cuántos días tiene la semana?»", "¿Cómo cuidan las lechugas?", "Busca saber más del huerto.")],
   [E("Dos preguntas sobre el paseo: A) «¿A qué hora salimos?» y B) «¿Hay paseo?». Si el texto ya dijo que hay paseo, ¿cuál es mejor?", "A", "B repite algo ya dicho."),
    E("¿Por qué es importante esperar el turno para preguntar?", "Para respetar al hablante y escuchar", "Así todos se oyen.")],
   [E(f"Escucha: {PASEO} ¿Cuál es una buena pregunta de aclaración sobre algo que no se dijo: «¿A qué hora salimos?» o «¿Saldremos temprano?»", "¿A qué hora salimos?", "Pide un dato que falta; lo otro ya se dijo."),
    E(f"Escucha: {TALLER} ¿Cuál pregunta pide una razón: «¿Por qué hay que llevar botellas limpias?» o «¿Cuántas botellas hay que llevar?»", "¿Por qué hay que llevar botellas limpias?", "Empieza con por qué y pide una razón.")]),
  [E("Tu profesora anuncia: «Mañana habrá una prueba de lectura». No dijo a qué hora. ¿Qué preguntas: «¿A qué hora será la prueba?» o «¿Habrá prueba?»", "¿A qué hora será la prueba?", "Pide el dato que falta.")],
  [E("¿Qué pregunta aclara una duda?", "La que pide un dato que falta", "Aclara lo que no se dijo."),
   E("¿Qué pregunta profundiza?", "La que busca saber más", "Pide razones o detalles."),
   E("¿Debo esperar mi turno para preguntar? Responde sí o no.", "Sí", "Respeta al hablante.")],
  ("Pide a un adulto que lea esto: «Esta tarde llegará una visita al colegio. Será una escritora que nos leerá un cuento. Debemos esperarla en el patio». Escribe dos preguntas: una para aclarar algo que no se dijo y otra para profundizar. Después escribe qué datos te faltaron.", "Aclarar: ¿A qué hora llega? Profundizar: ¿Por qué escribe cuentos? Faltaron: la hora y el nombre.", ["una pregunta de aclaración", "una de profundización", "identifica datos faltantes"], ["dos preguntas escritas", "lista de datos faltantes"], ["preguntar lo ya dicho", "preguntas muy largas"], "Hazle tus preguntas a otra persona y comprueba si las entiende."),
  "Escucha una noticia y piensa una pregunta que te quede.",
  "Escribe cuatro preguntas sobre un texto oral que escuches hoy, dos de aclaración y dos para profundizar.")

L(OA24, 5,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los dos textos de cada ejercicio.",
  "Aprenderé a relacionar dos textos orales sobre un mismo tema, buscando qué tienen en común y en qué se diferencian.",
  ["Sé identificar el propósito de un texto oral.", "Sé registrar información explícita."],
  ["A veces escuchas dos textos sobre un mismo tema. Pueden tener propósitos distintos. Uno explica cómo ocurre algo y otro informa un hecho. Relacionarlos es ver qué tienen en común y en qué se diferencian.",
   "Por ejemplo, un texto explica cómo se forma la lluvia y otro cuenta que ayer llovió en un pueblo. Ambos hablan de la lluvia. El primero explica el proceso y el segundo informa un hecho reciente. Se complementan: el primero ayuda a entender por qué llovió.",
   "Para compararlos, anota el tema, el propósito y los datos de cada uno. Luego pregunta: ¿qué dice uno que el otro no? ¿Coinciden en algo? Así comprendes mejor el tema que si solo escucharas uno."],
  [("relacionar", "unir dos ideas o textos"), ("tema", "de qué trata un texto"), ("complementar", "agregar información que le faltaba al otro"), ("diferencia", "lo que cambia entre dos cosas"), ("coincidir", "ser igual en algo")],
  [("Encontrar el tema común", f"Escucha texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Cuál es el tema común?", ["El primero habla de la lluvia.", "El segundo también.", "El tema común es la lluvia."], "La lluvia"),
   ("Ver la diferencia", "En esos dos textos, ¿cuál explica cómo se forma la lluvia y cuál informa un hecho?", ["El primero explica un proceso.", "El segundo cuenta que llovió ayer."], "El primero explica; el segundo informa")],
  [("Creer que los dos textos dicen lo mismo.", "Pueden tener propósitos distintos.", "Compara tema, propósito y datos."), ("Mezclar los datos de un texto con los del otro.", "Se confunde la información.", "Anota los datos de cada texto por separado.")],
  ([E(f"Escucha: {LLUVIA} ¿De qué tema trata?", "De cómo se forma la lluvia", "Lo dice el texto."),
    E(f"Escucha: {NOTICIA} ¿De qué tema trata?", "De que llovió en un pueblo", "Informa un hecho."),
    E("Relacionar dos textos es ver qué tienen en…", "Común y qué los diferencia", "Los dos textos se comparan.")],
   [E(f"Escucha: {LLUVIA} ¿Qué calienta el sol, según el texto: el agua del mar o la arena?", "El agua del mar", "Lo dice el texto."),
    E(f"Escucha: {NOTICIA} ¿Qué usaron los vecinos?", "Paraguas", "Lo dice el texto."),
    E(f"Texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Hablan del mismo tema? Responde sí o no.", "Sí", "Ambos hablan de la lluvia.")],
   [E(f"Texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Cuál explica un proceso: el primero o el segundo?", "El primero", "Explica cómo se forma."),
    E(f"Texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Cuál informa un hecho reciente: el primero o el segundo?", "El segundo", "Cuenta que ayer llovió."),
    E(f"Texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Cuál dato del segundo texto habla de lo que pasará después: «Hoy habrá sol por la tarde» o «Las calles se mojaron»?", "Hoy habrá sol por la tarde", "Es un dato del segundo texto.")],
   [E("Si un texto explica por qué llueve y otro informa que llovió ayer, ¿cómo se complementan?", "El primero ayuda a entender por qué llovió", "Uno explica el proceso del otro."),
    E("Un niño dice que los dos textos de la lluvia tienen el mismo propósito. ¿Es cierto? Responde sí o no y por qué.", "No, uno explica y el otro informa", "Tienen propósitos distintos.")],
   [E(f"Texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Cuál es una coincidencia entre los dos textos: «los dos hablan de la lluvia» o «los dos explican un proceso»?", "Los dos hablan de la lluvia", "Es el tema común."),
    E(f"Texto 1: {LLUVIA} Texto 2: {NOTICIA} ¿Cuál es una diferencia entre ellos: «uno explica cómo se forma y el otro informa un hecho» o «los dos hablan de la lluvia»?", "Uno explica cómo se forma y el otro informa un hecho", "Cambia el propósito.")]),
  [E("Escuchas en la radio una noticia sobre una plaza nueva y luego una explicación de cómo se cuidan los árboles de una plaza. ¿Qué tema tienen en común: la plaza o el fútbol?", "La plaza", "Ambos tratan de plazas.")],
  [E("¿Qué comparo al relacionar dos textos?", "Tema, propósito y datos", "Así veo coincidencias y diferencias."),
   E("¿Pueden dos textos del mismo tema tener propósitos distintos? Responde sí o no.", "Sí", "Uno puede explicar y otro informar."),
   E("¿Qué es complementar?", "Agregar información que falta", "El segundo completa al primero.")],
  ("Pide a un adulto que lea dos textos. Texto A: «Las semillas necesitan agua y luz para germinar. Primero crecen las raíces y luego el tallo». Texto B: «Esta mañana, el curso de tercero plantó semillas de poroto en vasos. Las pusieron junto a la ventana». Escribe el tema común, el propósito de cada uno y una cosa que uno dice y el otro no.", "Tema: las semillas. A explica cómo germinan; B informa lo que hizo el curso. A dice que crecen primero las raíces; B dice dónde pusieron los vasos.", ["dice el tema común", "dice el propósito de cada texto", "compara un dato"], ["tema", "dos propósitos", "una diferencia"], ["creer que dicen lo mismo", "mezclar datos"], "Compara tus respuestas con otra persona y revisen los datos."),
  "Escucha dos programas sobre un mismo tema y di qué los une.",
  "Escribe dos textos de dos oraciones sobre el mismo tema, uno que explique y otro que informe.")

L(OA24, 6,
  "Este cuaderno, lápiz y un adulto que lea en voz alta los textos de cada ejercicio.",
  "Aprenderé a inferir información implícita de un texto oral y a formular una opinión apoyada en lo que escuché.",
  ["Sé identificar información explícita.", "Sé que una opinión se apoya con razones."],
  ["La información implícita es la que no se dice directamente, pero se puede descubrir con las pistas del texto. Descubrirla es hacer una inferencia. Si escuchas «Se frotaba las manos y temblaba», puedes inferir que tenía frío.",
   "Para inferir, junta tres cosas: lo que dice el texto, lo que sabes del mundo y lo que tiene sentido. «Luis estaba solo, con la mirada en el suelo» sugiere que se sentía triste, pero no lo dice. Por eso se infiere: es una idea probable.",
   "Una opinión es lo que tú piensas sobre algo. Se dice con «Creo que… porque…». Debe tener una razón basada en el texto. «Creo que Luis necesita compañía porque estaba solo y nadie le hablaba». Así tu opinión se apoya en evidencias."],
  [("información implícita", "la que no se dice, pero se puede descubrir"), ("inferencia", "idea que descubro con las pistas del texto"), ("opinión", "lo que pienso sobre algo"), ("evidencia", "dato del texto que apoya mi idea"), ("probable", "que es posible o seguro")],
  [("Hacer una inferencia", f"Escucha: {LLEGO} ¿Qué puedes inferir sobre cómo se sentía la tía?", ["Se frotaba las manos y temblaba.", "Se sentó cerca de la estufa.", "Tenía frío."], "Que tenía frío"),
   ("Dar una opinión con evidencia", f"Escucha: {LUIS} ¿Qué opinas? Usa «Creo que... porque...».", ["Luis estaba solo.", "Nadie le hablaba.", "Creo que necesita compañía."], "Creo que Luis necesita compañía porque estaba solo y nadie le hablaba")],
  [("Inventar una inferencia sin pistas.", "No tiene apoyo.", "Usa lo que dice el texto."), ("Dar una opinión sin razón.", "No convence.", "Agrega «porque» y un dato.")],
  ([E("La información implícita es la que el texto…", "No dice directamente", "Se descubre con pistas."),
    E("Una inferencia es una idea que descubro con…", "Las pistas del texto", "No es adivinar sin base."),
    E("Una opinión se dice con «Creo que... porque...». ¿Lleva una razón? Responde sí o no.", "Sí", "Se apoya en el texto.")],
   [E(f"Escucha: {LLEGO} ¿Qué dice directamente el texto: que se sentó cerca de la estufa o que tenía frío?", "Que se sentó cerca de la estufa", "El frío no se dice, se infiere."),
    E(f"Escucha: {LUIS} ¿Qué estaba haciendo Luis: sentado solo o jugando con otros?", "Sentado solo", "Lo dice el texto."),
    E(f"Escucha: {LLEGO} ¿Qué se frotaba la tía?", "Las manos", "Lo dice el texto.")],
   [E(f"Escucha: {LUIS} ¿Qué puedes inferir: que Luis se sentía triste o que estaba muy contento?", "Que se sentía triste", "Estaba solo, miraba el suelo y nadie le hablaba."),
    E(f"Escucha: {LLEGO} ¿Qué inferencia tiene apoyo: que la tía tenía frío o que tenía calor?", "Que tenía frío", "Se frotaba las manos y temblaba."),
    E(f"Escucha: {PELICULA} ¿Qué puedes inferir: que la niña está sorprendida y contenta o que está enojada?", "Que está sorprendida y contenta", "Se tapa la boca y sonríe frente a los globos.")],
   [E(f"Escucha: {LUIS} Un niño dice «Creo que Luis es el más fuerte del curso». ¿Tiene apoyo en el texto? Responde sí o no.", "No", "El texto no habla de fuerza."),
    E("¿Por qué una inferencia es una idea probable y no segura?", "Porque el texto no lo dice directamente", "Se descubre con pistas.")],
   [E(f"Escucha: {LUIS} Completa con una razón: «Creo que Luis necesita compañía porque ___». Elige entre nadie le hablaba o tenía una mochila.", "Nadie le hablaba", "Es la razón que apoya su opinión."),
    E(f"Escucha: {LLEGO} Completa: «Creo que la tía necesitaba calor porque ___». Elige: temblaba y se sentó cerca de la estufa o traía bolsas llenas.", "Temblaba y se sentó cerca de la estufa", "Es la evidencia del texto.")]),
  [E("Tu profesora dice: «Nico entró con las botas llenas de barro y el paraguas mojado». ¿Qué puedes inferir: que llovió o que hacía calor?", "Que llovió", "Las botas con barro y el paraguas mojado lo sugieren.")],
  [E("¿Cómo se llama descubrir lo que no se dice?", "Inferir", "Se usa pistas."),
   E("¿Qué debe tener una opinión?", "Una razón o evidencia", "Se apoya en el texto."),
   E("¿Una inferencia siempre está escrita en el texto? Responde sí o no.", "No", "Se descubre con pistas.")],
  ("Pide a un adulto que lea esto: «Cuando entré a la sala, mi compañera Sol tenía los ojos brillantes y no paraba de sonreír. Sostenía una carta con un sello grande». Escribe una inferencia sobre cómo se sentía Sol y una opinión con «Creo que... porque...». Cada una debe tener una evidencia del texto.", "Inferencia: Sol estaba contenta, porque sonreía. Opinión: Creo que la carta traía buenas noticias, porque Sol sonreía y tenía los ojos brillantes.", ["escribe una inferencia con evidencia", "escribe una opinión con razón", "usa datos del texto"], ["una inferencia", "una opinión"], ["inferir sin pistas", "opinar sin razón"], "Comparte tu opinión con otra persona y escucha la suya."),
  "Escucha una anécdota y di qué puedes inferir.",
  "Escribe una inferencia y una opinión sobre una escena que viste hoy, con una razón cada una.")
